import { set } from 'mongoose';
import './FriendRequest.css';

function  FriendRequest({activeUser, user, requestsUsers, setRequestsUsers}) {
    const handleAcceptClick = async () => {
        await fetch('http://localhost:8080/api/users/' + activeUser.email + '/friends/' + user.email, {
            method: 'PATCH',
            headers: {
                'Authorization': `Bearer ${activeUser.token}`
            }
        });
        updateList(user);
    } 
    
    //this or friendRec?
    const handleDeqlineClick = async () => {
        await fetch('http://localhost:8080/api/users/' + activeUser.email + '/friendRec/' + user.email, {
            method: 'DELETE',
            headers: {
                'Authorization': `Bearer ${activeUser.token}`
            }
        });
        updateList(user);
    }

    const updateList = (removedUser) => {
        const index = requestsUsers.indexOf(user => user.email === removedUser.email);
        requestsUsers.splice(index, 1);
        setRequestsUsers([...requestsUsers]);
    }
    




    return (    
        <ul className="Request">
            <li className="list-group-item d-flex  align-items-center">
                    <img src={user.picture} className="card-img-bottom-user" alt="userPic"></img>
                    <span className = "name ">{user.displayName}</span>
                    <button type="button" class="btn btn-primary" onClick={handleAcceptClick}>
                         <span >Accept</span>
                    </button>
                    <button type="button" class="btn btn-light" onClick={handleDeqlineClick}>
                         <span >Decline</span>
                    </button>
            </li> 
        </ul>      
    );    

}
export default FriendRequest;
